CREATE TABLE IF NOT EXISTS "clients" (
  "id" INTEGER PRIMARY KEY NOT NULL,
  "companyname" VARCHAR(255) NOT NULL,
  "contactperson" VARCHAR(255),
  "email" VARCHAR(320),
  "phone" VARCHAR(64),
  "address" TEXT,
  "industry" VARCHAR(128),
  "activitylevel" VARCHAR(32) NOT NULL DEFAULT 'medium',
  "notes" TEXT,
  "createdat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedat" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "managercustomerkey" VARCHAR(64),
  "latitude" DOUBLE PRECISION,
  "longitude" DOUBLE PRECISION,
  "geocodesource" VARCHAR(32),
  "geocodedat" TIMESTAMP,
  "outstandingbalance" NUMERIC(12,2) NOT NULL DEFAULT '0',
  "oldestunpaiddate" TIMESTAMP,
  "excelclientid" INTEGER
);

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('clients','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM "clients"),1), true);
